\label{K-cntx}
	{\rm \cite{howlader2021dbalogic} A {\it Kripke context} based on a context $\mathbb{K}:=(G,M,I)$ is a triple $\mathbb{KC}:=((G,R),(M,S),I)$, where $R,S$ are relations on $G$ and $M$ respectively.


	}

\label{pro1}
	{\rm \cite{vormbrock} \noindent 

		\begin{enumerate}
			\item $\textbf{D}_{\sqcap}:=(D_{\sqcap},\sqcap,\vee,\neg,\bot,\neg\bot)$ is a {\rm Boolean algebra} whose order relation is the restriction of $\sqsubseteq$ to $D_{\sqcap}$ and is denoted by $\sqsubseteq_{\sqcap}$.
			\item $\textbf{D}_{\sqcup}:=(D_{\sqcup},\sqcup,\wedge,\lrcorner,\top,\lrcorner\top)$ is a {\rm Boolean algebra} whose order relation is the restriction of $\sqsubseteq$ to $D_{\sqcup}$ and it is denoted by $\sqsubseteq_{\sqcup}$.
			\item $x\sqsubseteq y$ if and only if $x\sqcap x\sqsubseteq y\sqcap y$ and $x\sqcup x\sqsubseteq y\sqcup y$ for $x,y\in D$, that is, $x_{\sqcap}\sqsubseteq_{\sqcap} y_{\sqcap}$ and $x_{\sqcup}\sqsubseteq y_{\sqcup}$.
	\end{enumerate}}

\label{pro1.5}
	{\rm \cite{kwuida2007prime}
		Let 

		$x,y,a\in D$. Then the following hold.
		\begin{enumerate}
			\item $x\sqcap\bot=\bot$ and $x\sqcup\bot=x\sqcup x$ that is $\bot\sqsubseteq x$.
			\item $x\sqcup \top=\top$ and $x\sqcap \top=x\sqcap x$ that is $x\sqsubseteq \top$.
			\item $x=y$ implies that $x\sqsubseteq y$ and $y\sqsubseteq x$.
			\item $x\sqsubseteq y$ and $y \sqsubseteq x$ if and only if $x\sqcap x=y\sqcap y$ and $x\sqcup x = y\sqcup y$.
			\item $x\sqcap y\sqsubseteq x,y\sqsubseteq x\sqcup y, x\sqcap y\sqsubseteq y,x\sqsubseteq x\sqcup y$.
			\item $x\sqsubseteq y$ implies $x\sqcap a\sqsubseteq y\sqcap a$ and $x\sqcup a\sqsubseteq y\sqcup a$. 
	\end{enumerate}}

\label{botom neg and ordered}
	{\rm \cite{howlader2021dbalogic} 

	For all $a,b\in D$, the following hold.
		\begin{enumerate}
			\item If $a\sqcap b=\bot$ then $a\sqcap a\sqsubseteq \neg b$.
			\item If $a\sqcap a\sqsubseteq \neg b$ then $a\sqcap b\sqsubseteq \bot$.
			\item If $a\sqcup b=\top$ then $\lrcorner b\sqsubseteq a\sqcup a$.
			\item If $\lrcorner b\sqsubseteq a\sqcup a$ then $\top\sqsubseteq a\sqcup b$.
		\end{enumerate}
		In particular, if $\textbf{D}$ is a cdBa then $a\sqcap b=\bot$ if and only if $a\sqcap a\sqsubseteq \neg b$, and  $a\sqcup b=\top$ if and only if $\lrcorner b\sqsubseteq a\sqcup a$.}

\label{compar-ideal}
	{\rm \cite{howlader3}                                
		$\mathcal{F}_{p}(\textbf{D})=\mathcal{F}_{pr}(\textbf{D})$ and $\mathcal{I}_{p}(\textbf{D})=\mathcal{I}_{pr}(\textbf{D})$.}

\label{lema1}
	{\rm \cite{wille}                              
		\begin{enumerate}
			\item For any filter $F$ of $\textbf{D}$, $F\cap D_{\sqcap}$ and $F\cap D_{\sqcup}$ are filters of the Boolean algebras $\textbf{D}_{\sqcap}$, $\textbf{D}_{\sqcup}$ respectively.
			\item Each filter $F_{0}$ of the Boolean algebra $\textbf{D}_{\sqcap}$ is the base of some filter $F$ of $\textbf{D}$ such that $F_{0}=F\cap D_{\sqcap}$. Moreover if $F_{0}$ is prime, $F\in\mathcal{F}_{p}(\textbf{D})$. 
		\end{enumerate}
		Similar results can be proved for ideals of dBas. }

\label{protconcept algebra}
	{\rm \cite{wille} \noindent 

		$\underline{\mathfrak{H}}(\mathbb{K}):= (\mathfrak{H}(\mathbb{K}), \sqcap,\sqcup,\neg,\lrcorner,\top,\bot)$ is a  pdBa.


	}

\label{cs}
\noindent
{\rm \cite{wille} \begin{enumerate}
\item $\mathfrak{H}(\mathbb{K}):=\mathfrak{H}(\mathbb{K})_{\sqcap}\cup \mathfrak{H}(\mathbb{K})_{\sqcup}$.
\item $\mathcal{B}(\mathbb{K}):=\mathfrak{H}(\mathbb{K})_{\sqcap}\cap \mathfrak{H}(\mathbb{K})_{\sqcup}$.
\end{enumerate}}

\label{complement of Fx}
	{\rm \cite{wille,howlader2020} Let  $x\in D$. Then the following hold.
		\begin{enumerate}
			\item $(F_{x})^{c}=F_{\neg x}$ and $(I_{x})^{c}=I_{\lrcorner x}$.
			\item $F_{x\sqcap y}=F_{x}\cap F_{y}$ and $I_{x\sqcup y}=I_{x}\cap I_{y}$.
	\end{enumerate}}

\label{tdBadual}
	{\rm \cite{howlader2021dbalogic} Let $\mathfrak{D}$ be a tpdBa. Then for all $a\in D$,                                                                                                                                            
		\begin{enumerate}
			\item $\textbf{I}^{\delta}\textbf{I}^{\delta}(a)=\textbf{I}^{\delta}(a)$ and $\textbf{C}^{\delta}\textbf{C}^{\delta}(a)=\textbf{C}^{\delta}(a)$.
			\item  $a\sqcap a\sqsubseteq \textbf{I}^{\delta}(a)$ and $\textbf{C}^{\delta}(a)\sqsubseteq a\sqcup a$.
		\end{enumerate} 
	}

\label{full-complexalg}
	{\rm \cite{howlader2021dbalogic} Let $\mathbb{KC}:=((G,R),(M,S),I)$ be a Kripke context. The {\it  complex algebra} of $\mathbb{KC}$, $\underline{\mathfrak{H}}^{+}(\mathbb{KC}):=(\mathfrak{H}(\mathbb{K}),\sqcup,\sqcap,\neg,$ $\lrcorner,\top,\bot,f_{R},f_{S})$, is the expansion  of the algebra $\underline{\mathfrak{H}}(\mathbb{K})$ of semiconcepts with the operators $f_{R}$ and $f_{S}$. 


	}

\label{complex algebra}
	{\rm \cite{howlader2021dbalogic} Let $\mathbb{KC}:=((G,R),(M,S),I)$ be a Kripke context based on the context $\mathbb{K}:=(G, M, I)$, $\underline{\mathfrak{H}}^{+}(\mathbb{KC}):=(\mathfrak{H}(\mathbb{K}),\sqcup,\sqcap,\neg,\lrcorner,\top,\bot,f_{R},f_{S})$ is a pdBao.

	}

{\rm \cite{howlader2021dbalogic} \noindent Let  $\mathbb{KC}:=((G,R),(M,S),I)$ be a Kripke context. 
		\begin{enumerate} 
			\item $\mathbb{KC}$ is {\it reflexive  from the left}, if $R$ is reflexive. 
			\item $\mathbb{KC}$ is {\it reflexive from the right}, if $S$ is reflexive. 
			\item $\mathbb{KC}$ is {\it reflexive}, if it is reflexive from both left and right.







		\end{enumerate}
		The cases for {\it symmetry} and {\it transitivity} of $\mathbb{KC}$ are similarly defined.}

\label{pure complex algebra]}
	{\rm \cite{howlader2021dbalogic} Let $\mathbb{KC}:=((G,R),(M,S),I)$ be a reflexive and transitive Kripke context. Then 
		$\underline{\mathfrak{H}}^{+}(\mathbb{KC})$  is a tpdBa.
	}

\label{canonical relations}
	{\rm \cite{howlader2021dbalogic} Let $\mathfrak{O}:=(D,\sqcup,\sqcap,\neg,\lrcorner,\top,\bot, \textbf{I}, \textbf{C})$ be a pdBao. The following hold.
		\begin{enumerate}
			\item  For all $u,u_{1}\in \mathcal{F}_{p}(\textbf{D})$, $uRu_{1}$ if and only if for all $a\in D$, $\textbf{I}a\in u$ implies that $a\in u_{1}$.
			\item  For all $v,v_{1}\in \mathcal{I}_{p}(\textbf{D})$, $vSv_{1}$ if and only if for all $a\in D$, $\textbf{C}a\in v$ implies that $a\in v_{1}$.
	\end{enumerate}}

\label{canonical box and dimon} 
	{\rm \cite{howlader2021dbalogic} Let $\mathfrak{O}$ be a pdBao and $\mathbb{KC}(\mathfrak{O}):=((\mathcal{F}_{p}(\textbf{D}),R), (\mathcal{I}_{p}(\textbf{D}),S),\Delta)$. For all $a\in D$: 
		\begin{enumerate}
			\item  $\overline{F_{a}}^{R}=F_{\textbf{I}^{\delta}(a)}$ and $\underline{F_{a}}_{R}=F_{\textbf{I}(a)}$.
			\item  $\overline{I_{a}}^{S}=I_{\textbf{C}^{\delta}(a)}$ and $\underline{I_{a}}_{S}=I_{\textbf{C}(a)}$.
	\end{enumerate}}

\label{rtdBao}
	{\rm \cite{howlader2021dbalogic} A pdBao $\mathfrak{O}:=(D,\sqcup,\sqcap,\neg,\lrcorner,\top,\bot, \textbf{I}, \textbf{C})$ is embeddable into the  complex algebra $\underline{\mathfrak{H}}^{+}(\mathbb{KC}(\mathfrak{O})):=(\mathfrak{H}(\mathbb{K}(\mathfrak{O})),\sqcup,\sqcap,\neg,\lrcorner,\top,\bot,f_{R},f_{S})$ of the Kripke context $\mathbb{KC}(\mathfrak{O})$. The map  $h:D\rightarrow \mathfrak{H}(\mathbb{K}(\textbf{D}))$ defined by $h(x):=(F_{x},I_{x})$ for all $x \in D$,  is the required embedding.



	}

\label{rttdBa}
	{\rm \cite{howlader2021dbalogic} 

		$\mathbb{KC}(\mathfrak{O}):=((\mathcal{F}_{p}(\textbf{D}), R), (\mathcal{I}_{p}(\textbf{D}), S), \Delta)$  is a reflexive  and transitive Kripke context.}

\label{rtdBa}
	{\rm \cite{howlader2021dbalogic} A  tpdBa $\mathfrak{O}$ is embeddable into the  complex algebra $\underline{\mathfrak{H}}^{+}(\mathbb{KC}(\mathfrak{O}))$ of the reflexive and transitive Kripke context $\mathbb{KC}(\mathfrak{O})$. 





	}

\label{drive rule1}
	{\rm  The following rules are derivable in  \textbf{PDBL}.
		\begin{multicols}{2}
			\item $\infer[(R6)]{B\mid  D\mid  \alpha\sqcap\alpha\vdash\beta\sqcap\gamma\mid  C\mid  E}{B\mid  \alpha\vdash\beta\mid  C & D\mid  \alpha\vdash \gamma\mid  E}$ 
			\item $\infer[(R7)]{B\mid  D\mid  \beta\sqcup \gamma\vdash\alpha\sqcup\alpha\mid  C\mid  E}{B\mid  \beta\vdash\alpha\mid  C & D\mid  \gamma\vdash \alpha\mid  E}$
		\end{multicols}

	}

\label{valution}
	{\rm 	 Let $\textbf{D}:=(D, \sqcap,\sqcup, \neg, \lrcorner, \top_{D}, \bot_{D})$ be a  pdBa. A {\it valuation} $v:\textbf{OV}\cup\textbf{PV}\cup \{\top, \bot\}\rightarrow D$ on $\textbf{D}$ is a map such that $v(p)\in D_{\sqcap}$, for all $p\in \textbf{OV}$,  $v(P)\in D_{\sqcup}$, for all $P\in \textbf{PV}$, $v(\top):=\top_{D}$ and  $v(\bot):=\bot_{D}$. $v$ is extended to the set $\mathfrak{F}$ of formulae by the following. }


	$\begin{array}{ll}

	1.~ v(\alpha\sqcup\beta):=v(\alpha)\sqcup v(\beta).&
	2.~ v(\alpha\sqcap\beta):=v(\alpha)\sqcap v(\beta).\\
	3.~ v(\neg \alpha):=\neg v(\alpha).&
	4.~ v(\lrcorner \alpha):=\lrcorner v(\alpha).


	\end{array}$

\label{satis-hyper-sequent}
	{\rm  A sequent $\alpha\vdash\beta$ is said to be  {\it satisfied} by a valuation $v$ on   a pdBa $\textbf{D}$ if and only if  $v(\alpha)\sqsubseteq v(\beta)$. An s-hypersequent $B$ is said to be  {\it satisfied} by a valuation $v$ on   a pdBa $\textbf{D}$ if and only if  $v$ satisfies one of the components of the s-hypersequent $B$.
		An s-hypersequent $B$ is  {\it true} in  $\textbf{D}$ if and only if  for  all valuations  $v$ on $\textbf{D}$, $v$ satisfies the s-hypersequent $B$. An s-hypersequent $B$  is {\it valid} in the class of all  pdBas if and only if it is true in  every  pdBa.
}

\label{sound1}
	{\rm If an s-hypersequent $G$ is provable in  \textbf{PDBL}  then it is  valid in the class of all pdBas.
}

\label{ldbm-dba}
	{\rm For any formulae $\alpha$ and $\beta$, the following are equivalent.
		\begin{enumerate}

			\item  $[\alpha] \sqsubseteq [\beta]$ in $\mathcal{L}(\mathfrak{F})$.
			\item $\alpha\vdash \beta$ is provable in \textbf{PDBL}.
		\end{enumerate}
	}

\label{lemmavalu}
	\noindent {\rm\begin{enumerate}
			\item For  $p\in \textbf{OV}$, $F_{[p]}^{\prime}=I_{[p]}$ and $P\in\textbf{PV}$, $I_{[P]}^{\prime}=F_{[P]}$.
			\item For $\phi, \sigma\in \mathfrak{F}$, $F_{[\phi]\sqcap [\sigma]}^{\prime}=I_{[\phi]\sqcap [\sigma]}$, $I_{[\phi]\sqcup [\sigma]}^{\prime}=F_{[\phi]\sqcup [\sigma]}$, $F_{\neg[\phi]}^{\prime}=I_{\neg[\phi]}$ and $I_{\lrcorner[\phi]}^{\prime}=F_{\lrcorner[\phi]}$.
	\end{enumerate}  }

\label{ldbm-dba1}
	{\rm The following are equivalent.
		\begin{enumerate}
			\item An s-hypersequent $G:\alpha_{1}\vdash\beta_{1}~|~\alpha_{2}\vdash\beta_{2}~|~\alpha_{3}\vdash\beta_{3}~|\ldots~|\alpha_{n}\vdash\beta_{n}$ is provable in  \textbf{PDBL}.
			\item $\alpha_{i}\vdash \beta_{i}$ is provable in \textbf{PDBL} for some $i\in\{1,2,\ldots,n\}$.
		\end{enumerate}
	}

\label{algvaludbao}
	{\rm A valuation $v$ on a pdBao $\mathfrak{O}:=(D,\sqcup,\sqcap,\neg,\lrcorner,\top_{D},\bot_{D},\textbf{I},\textbf{C})$, is a map  from $\textbf{OV}\cup\textbf{PV}\cup \{\top, \bot\}$ to $D$   that satisfies the conditions in Definition \ref{valution}  and the following  for the modal operators:










		$v(\square\alpha):=\textbf{I}(v(\alpha))$ and $v(\blacksquare\alpha):=\textbf{C}(v(\alpha))$.}

\label{ldbm-mdba}
	{\rm For any formulae $\alpha$ and $\beta$ the following are equivalent.
		\begin{enumerate}

			\item  $[\alpha] \sqsubseteq [\beta]$ in $\mathcal{L}_{\Sigma}(\mathfrak{F}_{1})$.
			\item $\alpha\vdash \beta$ is provable in $\textbf{MPDBL}\Sigma$.
		\end{enumerate}
	}

\label{ldbm-mdba1}
	{\rm The following are equivalent.
		\begin{enumerate}
			\item An s-hypersequent $G:\alpha_{1}\vdash\beta_{1}~|~\alpha_{2}\vdash\beta_{2}~|~\alpha_{3}\vdash\beta_{3}~|\ldots~|\alpha_{n}\vdash\beta_{n}$ is provable in  $\textbf{MPDBL}\Sigma$.
			\item $\alpha_{i}\vdash \beta_{i}$ is provable in $\textbf{MPDBL}\Sigma$ for some $i\in\{1,2,\ldots,n\}$.
		\end{enumerate}
	}

\label{sundandcompdbl}
	{\rm \noindent 
		\begin{enumerate}
			\item An s-hypersequent $G:\alpha_{1}\vdash\beta_{1}\mid\alpha_{2}\vdash\beta_{2}\mid\ldots\mid\alpha_{n}\vdash\beta_{n}$ is provable in \textbf{MPDBL} if and only if $G:\alpha_{1}\vdash\beta_{1}\mid\alpha_{2}\vdash\beta_{2}\mid\ldots\mid\alpha_{n}\vdash\beta_{n}$ is valid in the class of all  pdBaos.
			\item An s-hypersequent $G:\alpha_{1}\vdash\beta_{1}\mid\alpha_{2}\vdash\beta_{2}\mid\ldots\mid\alpha_{n}\vdash\beta_{n}$ is provable in \textbf{MPDBL4} if and only if $G:\alpha_{1}\vdash\beta_{1}\mid\alpha_{2}\vdash\beta_{2}\mid\ldots\mid\alpha_{n}\vdash\beta_{n}$ is valid in the class of all tpdBas.
	\end{enumerate}}

\label{pdBamodel}
	{\rm A model for \textbf{PDBL} is a pair $\mathbb{M}:=(\mathbb{K},v)$, where $\mathbb{K}=(G,M,R)$ is a context and   $v$ is a valuation on $\underline{\mathfrak{H}}(\mathbb{K})$.








	}

\label{satisfiction-set}
	{\rm Let $\mathbb{M}:=(\mathbb{K}, v)$ be a model and $\alpha, \beta\in \mathfrak{F}$.                     
		\begin{enumerate}
			\item $v_{1}(\alpha\sqcap\beta)=v_{1}(\alpha)\cap v_{1}(\beta)$ and $v_{2}(\alpha\sqcap\beta)=(v_{1}(\alpha)\cap v_{1}(\beta))^{\prime}$.
			\item $v_{1}(\alpha\sqcup\beta)=(v_{2}(\alpha)\cap v_{2}(\beta))^{\prime}$ and $v_{2}(\alpha\sqcup\beta)=v_{2}(\alpha)\cap v_{2}(\beta)$.
			\item $v_{1}(\neg\alpha)= v_{1}(\alpha)^{c}$ and  $v_{2}(\neg\alpha)= (v_{1}(\alpha)^{c})^{\prime}$.
			\item $v_{1}(\lrcorner \alpha)= (v_{2}(\alpha)^{c})^{\prime}$ and $v_{2}(\lrcorner \alpha)= (v_{2}(\alpha)^{c}$.
			\item $v_{1}(\top)=G$ and $v_{2}(\top)=\emptyset$.
			\item $v_{1}(\bot)=\emptyset$ and $ v_{2}(\bot)=M$.
	\end{enumerate}}

We given the proofs of 1 and 3. 2 and 4 follow dually. 5 and 6 follow directly from Definition \ref{satisfiction and co-satisfiction}.
\begin{eqnarray*}
		1.~v_{1}(\alpha\sqcap\beta)
		&=&\{g\in G~|~\mathbb{M},g\models \alpha\sqcap\beta\}
		=\{g\in G~|~\mathbb{M},g\models \alpha~\mbox{and}~\mathbb{M},g\models \beta\}\\
		&=&\{g\in G~|~ g\in v_{1}(\alpha)~\mbox{and}~g\in v_{1}(\beta)\}
		= v_{1}(\alpha)\cap v_{1}(\beta).
	\end{eqnarray*}
	\begin{eqnarray*}	~~~v_{2}(\alpha\sqcap\beta)&=&\{m\in M~|~\mathbb{M},m\succ \alpha\sqcap\beta\}\\
		&=&\{m\in M~|~\mbox{for all}~ g\in G( \mathbb{M},g\models \alpha\sqcap\beta \Longrightarrow gRm)\}\\
		&=&\{m\in M~|~\mbox{for all}~ g\in G( \mathbb{M},g\models \alpha~\mbox{and}~\mathbb{M},g\models\beta \Longrightarrow gRm)\}\\
		&=&\{m\in M~|~\mbox{for all}~ g\in G( g\in v_{1}(\alpha)~\mbox{and}~g\in v_{1}(\beta) \Longrightarrow gRm)\}\\
		&=&\{m\in M~|~\mbox{for all}~ g\in G( g\in v_{1}(\alpha)\cap v_{1}(\beta) \Longrightarrow gRm)\}\\
		&=&  (v_{1}(\alpha)\cap v_{1}(\beta))^{\prime}.
	\end{eqnarray*}

















	\begin{eqnarray*}
		3.~v_{1}(\neg\alpha)
		&=&\{g\in G~|~\mathbb{M},g\models \neg\alpha\}
		=\{g\in G~|~\mathbb{M},g\not\models \alpha\}\\
		&=&\{g\in G~|~ g\notin v_{1}(\alpha)\}
		=(v_{1}(\alpha))^{c}.
	\end{eqnarray*}
	\begin{eqnarray*}
		~~~v_{2}(\neg\alpha)
		&=&\{m\in M~|~\mathbb{M},m\succ\neg \alpha\}\\
		&=&\{m\in M~|~\mbox{for all}~ g\in G( \mathbb{M},g\not\models \alpha \Longrightarrow gRm)\}\\
		&=&\{m\in M~|~\mbox{for all}~ g\in G( g\notin v_{1}(\alpha) \Longrightarrow gRm)\}\\
		&=&\{m\in M~|~\mbox{for all}~ g\in G( g\in (v_{1}(\alpha))^{c} \Longrightarrow gRm)\}\\
		&=&(v_{1}(\alpha))^{c\prime}.
	\end{eqnarray*}

\label{PDBL-valution}
	{\rm                                                                                                            
		For any formulae $\alpha, \beta\in \mathfrak{F}$,

		\noindent	\begin{enumerate}
			\item $(v_{1}(\alpha\sqcap\beta), v_{2}(\alpha\sqcap\beta))=(v_{1}(\alpha), v_{2}(\alpha))\sqcap (v_{1}(\beta),v_{2}(\beta))$.
			\item $(v_{1}(\alpha\sqcup\beta), v_{2}(\alpha\sqcup\beta))=(v_{1}(\alpha), v_{2}(\alpha))\sqcup (v_{1}(\beta),v_{2}(\beta))$.
			\item $\neg (v_{1}(\alpha), v_{2}(\alpha))=(v_{1}(\neg\alpha), v_{2}(\neg\alpha))$ and $\lrcorner (v_{1}(\alpha), v_{2}(\alpha))=(v_{1}(\lrcorner\alpha), v_{2}(\lrcorner\alpha))$.



	\end{enumerate}}

\label{dfsatis}
	{\rm Let $\mathbb{M}$ be a model. For $\alpha,\beta\in \mathfrak{F}$  a sequent $\alpha\vdash\beta$ is said to be {\it satisfied} in the model $\mathbb{M}$ if and only if the following hold.
		\begin{enumerate}
			\item For all $g\in G$ $\mathbb{M},g\models\alpha$ implies that $\mathbb{M},g\models\beta$.
			\item For all $m\in M$ $\mathbb{M},m\succ \beta$ implies that $\mathbb{M},m\succ\alpha$.
	\end{enumerate}}

\label{satisdbl}
	{\rm Let $\mathbb{M}:=(\mathbb{K}, v)$ be a model. For $\alpha,\beta\in \mathfrak{F}$  a sequent $\alpha\vdash\beta$ is  satisfied in the model $\mathbb{M}$  if and only if $v(\alpha)\sqsubseteq v(\beta)$ in $\mathfrak{H}(\mathbb{K})$, that is, $\alpha\vdash \beta$ is satisfied by $v$ on the pdBa  $\underline{\mathfrak{H}}(\mathbb{K})$.

	}

\label{s-hyper satisf}
	{\rm A hyper-sequent $G:\alpha_{1}\vdash\beta_{1}|\alpha_{2}\vdash\beta_{2}|. . .|\alpha_{n}\vdash\beta_{n}$ is said to be {\it satisfied} in a model $\mathbb{M}$ if and only if at least one of the components of $G$ is satisfied in $\mathbb{M}$.

		\noindent  $G$ is said to be {\it true} in $\mathbb{K}$ if and only if $G$ is satisfied in every model $\mathbb{M}$ based on $\mathbb{K}$.

		\noindent $G$ is said to be {\it valid} in $\mathcal{K}$ if and only if $G$ is true in every $\mathbb{K}$ for all $\mathbb{K}\in \mathcal{K}$.}

\label{pdbl case sound}
	{\rm If a hyper-sequent $G:\alpha_{1}\vdash\beta_{1}|\alpha_{2}\vdash\beta_{2}|\alpha_{3}\vdash\beta_{3}|\ldots|\alpha_{n}\vdash\beta_{n}$ is provable in  \textbf{PDBL}  then it is valid in $\mathcal{K}$.
	}

\label{modalmodel}
	{\rm A model for \textbf{MPDBL} is a pair $\mathbb{M}:=(\mathbb{KC}, v)$, where $\mathbb{KC}:=((G,R), (M,S), I)$ is a Kripke context and $v$ is a valuation on $\underline{\mathfrak{H}}(\mathbb{K})$.

	}

\label{modal formula satisf}
	{\rm Let $\mathbb{M}:=(\mathbb{KC}, v)$ be a model based on the Kripke context $\mathbb{KC}:=((G,R), (M,S), I)$. In the following $g\in G$ and $m\in M$.
		\begin{enumerate}
			\item[15.] $\mathbb{M},g\models \square\alpha$ if and only if for all $g_{1}\in G$ ($gRg_{1}\Longrightarrow\mathbb{M},g_{1}\models \alpha$).
			\item[16.] $\mathbb{M},m\succ\square\alpha$ if and only if for all $g, g_{1}\in G(( gRg_{1} \Longrightarrow \mathbb{M},g_{1}\models\alpha)\Longrightarrow gIm).$
			\item[17.] $\mathbb{M},m\succ\blacksquare\alpha$ if and only if for all $m_{1}\in M$ ($mSm_{1}\Longrightarrow\mathbb{M},m_{1}\succ\alpha$).
			\item[18.] $\mathbb{M},g\models \blacksquare\alpha$ if and only if for all $m,m_{1}\in M(( mSm_{1}\Longrightarrow\mathbb{M},m_{1}\succ\alpha)\Longrightarrow gIm)$
	\end{enumerate}}

\label{satdualmodope}
	{\rm For all $g\in G$ and for  all $m\in M$, the following hold.
		\begin{enumerate}
			\item $\mathbb{M},g\models\lozenge\alpha$ if and only if there exists $g_{1}\in G$ such that $gRg_{1}$ and $\mathbb{M},g_{1}\models\alpha$.
			\item $\mathbb{M},m\succ\lozenge\alpha$ if and only if for all $g\in G$  ((there exists $g_{1}\in G$ with $\mathbb{M},g_{1}\models \alpha$ and $gRg_{1}$) $ \Longrightarrow gIm$).
			\item $\mathbb{M},m\succ\blacklozenge\alpha$ if and only if there exists $m_{1}\in M$ such that $mSm_{1}$ and $\mathbb{M},m_{1}\succ\alpha$.
			\item $\mathbb{M},g\models\blacklozenge\alpha$ if and only if for all $m\in M$ ((there exists $m_{1}\in M$ with $mSm_{1}$ and $\mathbb{M},m_{1}\succ\alpha$)  $\Longrightarrow gIm$).
	\end{enumerate}}

\label{modal valuation}

	\noindent 	{\rm 
		\begin{enumerate}
			\item If $\alpha=\square\phi$ then $v_{1}(\alpha)=\underline{v_{1}(\phi)}_{R}$ and $v_{2}(\alpha)=(\underline{v_{1}(\phi)}_{R})^{\prime}$.
			\item  If $\alpha=\blacksquare\phi$ then $v_{1}(\alpha)=(\underline{v_{2}(\phi)}_{S})^{\prime}$ and $v_{2}(\alpha)=\underline{v_{2}(\phi)}_{S}$.
			\item  If $\alpha=\lozenge \phi$ then $v_{1}(\alpha)=\overline{v_{1}(\phi)}^{R}$ and $v_{2}(\alpha)=(\overline{v_{1}(\phi)}^{R})^{\prime}$.
			\item If $\alpha=\blacklozenge\phi$ then  $v_{1}(\alpha)=(\overline{v_{2}(\phi)}^{S})^{\prime}$ and $v_{2}(\alpha)=\overline{v_{2}(\phi)}^{S}$.
	\end{enumerate}}

\label{mpdbl-valuation}
